---RefreshWeaknessNode
---刷新解体效果节点
---@param weakVo WeakVo
function CommonTipsBoardWeakness:RefreshWeaknessNode(weakVo)
    local star = checkNumber(weakVo.weakStars[1])
    self:RefreshDescText(self.WeaknessRoundText, star, true)
    self.WeaknessDescText.text = string.gsub(weakVo.rageShow, ";", "\n")
end

---RefreshDormantNode
---刷新休眠状态节点
---@param weakVo WeakVo
function CommonTipsBoardWeakness:RefreshDormantNode(weakVo)
    self:RefreshDescText(self.DormantRoundText, weakVo.weakLength)
    --local text = string.gsub(weakVo.weakShow, "_round_", weakVo.weakLength)
    self.DormantDescText.text = string.gsub(weakVo.weakShow , ";", "\n")
end

function CommonTipsBoardWeakness:RefreshDescText(node, num, isRage)
    local isShow = checkInt(num) > 0
    KTool.SetActive(node.gameObject, isShow)
    if isShow then
        if isRage then
            node.text = localize("持续:<color=#1b459a>_num_星</color>", {_num_ = num })
        else
            node.text = localize("持续:<color=#1b459a>_num_回合</color>", {_num_ = num })
        end
    end
end


